import{_ as o,o as t,c as l,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"MCP 与 Agent 协议：从 Tool 集成到可组合能力","description":"","frontmatter":{"title":"MCP 与 Agent 协议：从 Tool 集成到可组合能力","date":"2026-08-29T00:00:00.000Z","isComment":true,"categories":["AI","Agent"],"tags":["MCP","Protocol","Tools"]},"headers":[],"relativePath":"31-mcp-and-agent-protocols.md","filePath":"31-mcp-and-agent-protocols.md","lastUpdated":1790425174000}'),i={name:"31-mcp-and-agent-protocols.md"};function r(d,e,s,n,c,h){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-与-agent-协议-从-tool-集成到可组合能力" tabindex="-1">MCP 与 Agent 协议：从 Tool 集成到可组合能力 <a class="header-anchor" href="#mcp-与-agent-协议-从-tool-集成到可组合能力" aria-label="Permalink to &quot;MCP 与 Agent 协议：从 Tool 集成到可组合能力&quot;">​</a></h1><blockquote><p>MCP 的价值不只是“多一个工具协议”，而是把能力提供方和 Agent 运行时之间的接口、资源和生命周期标准化。</p><p><strong>边界：</strong> 本篇管协议与能力发现。业务 Tool 设计见 <a href="./09-tools-system-design">09</a>，Skills 见 <a href="./23-skills-agent-bridge">23</a>。</p><p><strong>配套实验：</strong> <a href="./examples#04-mcp-能力服务">04 MCP 能力服务</a> — 同一套业务函数经官方 SDK 被 Client 发现；含 Tool、只读 Resource、Prompt，以及 stdio / HTTP。HTTP 可用 Bearer 映射角色。</p></blockquote><h2 id="tool、skills、rag、mcp-的边界" tabindex="-1">Tool、Skills、RAG、MCP 的边界 <a class="header-anchor" href="#tool、skills、rag、mcp-的边界" aria-label="Permalink to &quot;Tool、Skills、RAG、MCP 的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>解决的问题</th></tr></thead><tbody><tr><td>Tool</td><td>Agent 如何调用一个动作</td></tr><tr><td>RAG</td><td>Agent 如何查询外部知识</td></tr><tr><td>Skill</td><td>Agent 如何复用一套操作方法和约束</td></tr><tr><td>MCP</td><td>能力提供方如何以标准协议暴露 Tool、Resource 和 Prompt</td></tr></tbody></table><p>它们可以组合，但不能互相替代。MCP Server 仍然需要权限、超时、审计和输入校验。</p><h2 id="mcp-学习顺序" tabindex="-1">MCP 学习顺序 <a class="header-anchor" href="#mcp-学习顺序" aria-label="Permalink to &quot;MCP 学习顺序&quot;">​</a></h2><ol><li>写一个只读 Resource Server。本仓库 04 已暴露 <code>blog://posts/welcome</code>。</li><li>增加带 Zod Schema 的 Tool。</li><li>编写最小 Client，发现能力并调用 Tool。本仓库 04 已用内存传输、stdio 和 Streamable HTTP 跑通这一步。</li><li>增加鉴权、日志、错误映射和超时。04 的 HTTP 入口可用 Bearer token 映射 reader/writer，能力层带超时和 <code>onAudit</code> 审计回调；03 的 <code>runTool</code> 可包住 MCP <code>callTool</code>。</li><li>将现有 <code>ToolRegistry</code> 适配为 MCP Server。</li></ol><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li>暴露业务能力，不暴露过大的万能接口。</li><li>Tool 名称和参数保持稳定，兼容性优先。</li><li>返回结构化结果，同时提供人类可读摘要。</li><li>明确哪些操作只读、哪些操作有副作用。</li><li>不把密钥、内部路径和未脱敏数据写入返回值。</li><li>对 Resource 做版本和权限控制。</li></ul><h2 id="mcp-server-的验收标准" tabindex="-1">MCP Server 的验收标准 <a class="header-anchor" href="#mcp-server-的验收标准" aria-label="Permalink to &quot;MCP Server 的验收标准&quot;">​</a></h2><ul><li>能列出能力，并且描述与实际 Schema 一致。</li><li>非法参数在执行前被拒绝。</li><li>Tool 超时不会拖死 Agent 主循环。</li><li>重试不会重复执行不可逆操作。</li><li>日志能关联用户、租户、请求和 Tool 调用。</li><li>Server 重启后不会丢失需要持久化的业务状态。</li></ul><p>前六条在本仓库 04 均有可运行验证：Schema 与权限在能力层校验，handler 有 <code>timeoutMs</code> 且可通过 <code>AbortSignal</code> 真正中断，<code>publish_post</code> 用 <code>idempotencyKey</code> 去重，<code>onAudit</code> 记录角色、结果和 <code>requestId</code>，<code>MCP_STORE_PATH</code> 落盘保证重启不丢。租户字段和持久化 Trace 仍是后续方向。</p><h2 id="从本项目开始的实践" tabindex="-1">从本项目开始的实践 <a class="header-anchor" href="#从本项目开始的实践" aria-label="Permalink to &quot;从本项目开始的实践&quot;">​</a></h2><p>把 <a href="./09-tools-system-design">09 Tools</a> 中的天气、Wikipedia 或博客检索 Tool 分阶段迁移：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地函数 → ToolRegistry → MCP Server → Agent Client → 权限与审计</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>迁移过程中保持同一套业务函数和测试，协议层只负责适配，不要复制一套执行逻辑。</p><h2 id="后续方向" tabindex="-1">后续方向 <a class="header-anchor" href="#后续方向" aria-label="Permalink to &quot;后续方向&quot;">​</a></h2><ul><li>MCP 与 LangGraph、Mastra、AI SDK 的接入方式比较。</li><li>远程 MCP 的鉴权、租户隔离和部署。</li><li>多 Agent handoff 与 A2A 类协议的边界。</li><li>浏览器、文件系统、数据库等高风险能力的沙箱化。</li></ul><h2 id="与已有内容的关系" tabindex="-1">与已有内容的关系 <a class="header-anchor" href="#与已有内容的关系" aria-label="Permalink to &quot;与已有内容的关系&quot;">​</a></h2><ul><li>Skills 见 <a href="./23-skills-agent-bridge">23</a>。</li><li>Tool 系统见 <a href="./09-tools-system-design">09</a>。</li><li>开源 MCP 资源索引见 <a href="./github-ai">github-ai</a>。</li></ul>',20)])])}const m=o(i,[["render",r]]);export{u as __pageData,m as default};
